    invariant 0 <= idx2 <= n
    invariant steps <= 3 * idx2 + 2 * n + 2 * SortCost(n) + 1
    decreases n - idx2
  {
    if intervals[idx2][0] == Ldesc[0] && intervals[idx2][1] == Rasc[0] {
      found := true;
    }
    idx2 := idx2 + 1;
    steps := steps + 3;
  }
  var ans := 0;
  if found {
    var v := Rasc[1] - Ldesc[1];
