method Solve(n: int, a_list: seq<int>) returns (output: string, ghost steps: nat)
  requires n >= 1 && n == |a_list|
  ensures steps <= 2 * n * (CeilLog2(n) + 1) + 4 * n + 10
{
  if n == 1 {
    output := IntToString(a_list[0]);
    steps := 2;
  } else {
    SortCostTreeBound(n);
    steps := 1 + SortCost(n);
    var s := SortInts(a_list);
