      steps := steps + (n - i) + i + 1;
    }
    output := IntToString(ans);
    steps := steps + 1;
  }
}

function SumRange(s: seq<int>, lo: int, hi: int): int
  requires 0 <= lo <= hi <= |s|
  decreases hi - lo
