  // Python does p.index(k), which raises ValueError when k is absent, so this
  // excludes no input Python answers.
  requires exists c :: 0 <= c < n && a_list[c] == k
  ensures steps <= 4 * n + 8
{
  steps := 1;
  var m := k;
  var p := a_list;
  var wIdx :| 0 <= wIdx < n && p[wIdx] == m;
  var cur := 0;
  while p[cur] != m
    invariant 0 <= cur <= wIdx
    invariant steps == cur + 1
    decreases wIdx - cur
  {
    cur := cur + 1;
    steps := steps + 1;
  }
  var pos := cur;
  var s: map<int, int> := map[];
  var cnt := 0;
  var length := 0;
  cur := pos;
  steps := steps + 1;
  while cur >= 0
    invariant -1 <= cur <= pos
    invariant steps == pos + 2 + 3 * (pos - cur)
    decreases cur + 1
  {
    if p[cur] <= m {
      cnt := cnt + 1;
    }
    length := length + 1;
    var key := 2 * cnt - length;
    if key in s {
      s := s[key := s[key] + 1];
    } else {
      s := s[key := 1];
    }
    cur := cur - 1;
    steps := steps + 3;
  }
  cur := pos;
  cnt := 0;
  length := 0;
  var ans := 0;
  steps := steps + 1;
  while cur < n
    invariant pos <= cur <= n
    invariant steps == 4 * pos + 6 + 4 * (cur - pos)
    decreases n - cur
  {
    if p[cur] <= m {
      cnt := cnt + 1;
    }
    length := length + 1;
    var k1 := length - 2 * cnt + 1;
    var k2 := length - 2 * cnt + 2;
    if k1 in s {
      ans := ans + s[k1];
    }
    if k2 in s {
      ans := ans + s[k2];
    }
    cur := cur + 1;
    steps := steps + 4;
  }
  output := IntToString(ans) + "\n";
  steps := steps + 2;
}
